mapper.select:
SELECT partner_id, partner_nm, last_content, last_sent_at,
       (SELECT COUNT(1) FROM MSGR_MESSAGE m2
         WHERE m2.sender_id = partner_id AND m2.receiver_id = #{value} AND m2.read_at IS NULL) AS unread_count
  FROM (
        SELECT DISTINCT ON (partner_id) partner_id, partner_nm, content AS last_content, sent_at AS last_sent_at
          FROM (
                SELECT receiver_id AS partner_id, receiver_nm AS partner_nm, content, sent_at FROM MSGR_MESSAGE WHERE sender_id = #{value}
                UNION ALL
                SELECT sender_id AS partner_id, sender_nm AS partner_nm, content, sent_at FROM MSGR_MESSAGE WHERE receiver_id = #{value}
               ) both_sides
         ORDER BY partner_id, sent_at DESC
       ) latest
 ORDER BY last_sent_at DESC
